Вот несколько шагов, которые вы можете выполнить для продажи токенов в частном порядке ранним инвесторам, прежде чем запустить токен на панели запуска:

1. Добавьте функцию для создания токенов, которая будет блокировать токены в контракте, пока они не будут выпущены.

2. Добавьте функцию, которая позволяет ранним инвесторам покупать токены в частном порядке.

3. Добавьте функцию, которая будет разблокировать токены, когда время предпродажи истечет.

4. Добавьте функцию, которая позволяет ранним инвесторам обменять свои токены на токены, выпущенные в публичном запуске.

5. Обновите функцию, которая позволяет ранним инвесторам обменять свои токены на токены, выпущенные в публичном запуске, чтобы она позволяла обменять только токены, которые были разблокированы в предпродажном периоде.

6. Добавьте функцию, которая позволяет пользователям покупать токены в публичном запуске.

7. Убедитесь, что ваша функция для выпуска токенов запускает только после того, как предпродажа истекла и все ранние инвесторы обменяли свои токены на токены, выпущенные в публичном запуске.

Вот несколько примеров кода, которые могут помочь вам реализовать эти функции:

```solidity
pragma solidity ^0.8.0;

contract Token {
    mapping(address => uint256) private _balances;

    event Transfer(address indexed from, address indexed to, uint256 value);

    constructor() {
        _mint(msg.sender, 1000000);
    }

    function _mint(address to, uint256 amount) private {
        _balances[to] += amount;
        emit Transfer(address(0), to, amount);
    }

    function _burn(address from, uint256 amount) private {
        _balances[from] -= amount;
        emit Transfer(from, address(0), amount);
    }

    function mint(address to, uint256 amount) public onlyOwner {
        _mint(to, amount);
    }

    function burn(address from, uint256 amount) public onlyOwner {
        _burn(from, amount);
    }

    function transfer(address to, uint256 amount) public virtual returns (bool) {
        address sender = msg.sender;
        if (amount == 0) {
            return true;
        }

        if (_balances[sender] < amount) revert InsufficientBalance();

        _balances[sender] -= amount;
        _balances[to] += amount;

        emit Transfer(sender, to, amount);

        return true;
    }

    function preSaleBuy(address buyer, uint256 amount) public onlyOwner {
        if (_balances[msg.sender] < amount) revert InsufficientBalance();

        _balances[msg.sender] -= amount;
        _balances[buyer] += amount;

        emit Transfer(msg.sender, buyer, amount);
    }

    function unlockTokens() public onlyOwner {
        _balances[msg.sender] = _balances[msg.sender] - 1000000;
    }

    function exchangePreSaleTokensForPublicTokens(uint256 amount) public {
        if (_balances[msg.sender] < amount) revert InsufficientBalance();

        _balances[msg.sender] -= amount;
        _balances[owner()] += amount;

        emit Transfer(msg.sender, owner(), amount);
    }

    function publicSaleBuy() public payable returns (bool) {
        uint256 amount = msg.value / 1 ether;
        if (amount == 0) revert InsufficientBalance();

        if (_balances[owner()] < amount) revert InsufficientBalance();

        _balances[owner()] -= amount;
        _balances[msg.sender] += amount;

        emit Transfer(owner(), msg.sender, amount);

        return true;
    }

    function _transfer(
        address from,
        address to,
        uint256 amount
    ) internal virtual {
        require(from != address(0), "ERC20: transfer from the zero address");
        require(to != address(0), "ERC20: transfer to the zero address");
        require(amount > 0, "ERC20: transfer amount must be greater than zero");

        _beforeTokenTransfer(from, to, amount);

        _balances[from] = _balances[from] - amount;
        _balances[to] = _balances[to] + amount;

        emit Transfer(from, to, amount);

        _afterTokenTransfer(from, to, amount);
    }

    function _beforeTokenTransfer(
        address from,
        address to,
        uint256 amount
    ) internal virtual {}

    function _afterTokenTransfer(
        address from,
        address to,
        uint256 amount
    ) internal virtual {}

    modifier onlyOwner() {
        require(msg.sender == owner(), "Ownable: caller is not the owner");
        _;
    }

    function owner() public view returns (address) {
        return 0xAb8483F64d9C6d1EcF9b849Ae677dD3315835cb2;
    }
}
```

В этом примере кода:

- `_mint` и `_burn` являются приватными функциями, которые используются для создания и уничтожения токенов.
- `mint` и `burn` являются публичными функциями, которые позволяют владельцу создавать и уничтожать токены.
- `transfer` является публичной функцией, которая позволяет пользователям передавать токены друг другу.
- `preSaleBuy` является публичной функцией, которая позволяет ранним инвесторам покупать токены в предпродажном периоде.
- `unlockTokens` является публичной функцией, которая разблокирует токены, которые ранние инвесторы купили в предпродажном периоде.
- `exchangePreSaleTokensForPublicTokens` является публичной функцией, которая позволяет ранним инвесторам обменять свои токены на токены, выпущенные в публичном запуске.
- `publicSaleBuy` является публичной функцией, которая позволяет пользователям покупать токены в публичном запуске.

