// Импортируйте необходимые пакеты
const { Client, GatewayIntentBits } = require('discord.js');
require('dotenv').config();

// Инициализируйте клиент
const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

// Подключите бота
client.on('ready', () => {
  console.log(`Бот ${client.user.username} запущен!`);
});

// Обработайте команду бан
client.on('interactionCreate', async interaction => {
  if (!interaction.isChatInputCommand()) return;

  if (interaction.commandName === 'ban') {
    // Проверьте, есть ли необходимые разрешения
    if (!interaction.member.permissions.has('BAN_MEMBERS')) {
      return interaction.reply({ content: 'Недостаточно прав для выполнения этой команды', ephemeral: true });
    }

    // Получите пользователя, которого необходимо заблокировать
    const user = interaction.options.getUser('user');

    // Проверьте, существует ли пользователь
    if (!user) {
      return interaction.reply({ content: 'Пользователь не найден', ephemeral: true });
    }

    // Проверьте, может ли пользователь быть заблокирован
    if (!interaction.guild.members.me.permissions.has('BAN_MEMBERS', { deny: true })) {
      return interaction.reply({ content: 'Недостаточно прав для выполнения этой команды', ephemeral: true });
    }

    // Заблокируйте пользователя
    try {
      await interaction.guild.bans.create(user, { reason: 'Команда бана' });
      return interaction.reply({ content: `Пользователь ${user} успешно заблокирован`, ephemeral: true });
    } catch (error) {
      console.error(error);
      return interaction.reply({ content: 'Ошибка при выполнении команды бана', ephemeral: true });
    }
  }
});

// Подключите клиента
client.login(process.env.DISCORD_TOKEN);
```

