      простыеЧисла.push(число);
    }
  });

  return простыеЧисла;

  // Функция, определяющая простые числа
  function isPrime(num) {
    if (num < 2) return false;
    if (num === 2) return true;
    if (num % 2 === 0) return false;

    for (let I = 3; I * I <= num; I += 2) {
      if (num % I === 0) return false;
    }

    return true;
  }
}

// Пример использования
const массив = [7, 17, 23, 29, 31];
const простыеЧисла = проверитьПростыеЧисла(массив);
console.log(простыеЧисла); // [7, 17, 23, 29, 31]
```

В этом случае функция `checkPrimeNumbers` возвращает массив простых чисел, а не выводит их на консоль. Вы можете вызвать эту функцию, чтобы получить массив простых чисел, и затем использовать этот массив в соответствии с вашими потребностями.

